CSS_COMPONENTES = """
.panel-card{margin-bottom:14px}
.panel-header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid var(--rule)}
.panel-title{font-family:'IBM Plex Sans',sans-serif;font-size:1rem;font-weight:600;color:var(--text);margin:0;display:flex;align-items:center;gap:8px}
.panel-meta{font-size:.72rem;color:var(--muted);font-family:'IBM Plex Mono',monospace;background:var(--raised);padding:3px 8px;border-radius:4px;border:1px solid var(--border)}
.spec-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.spec-tile{background:var(--raised);border:1px solid var(--border);border-radius:5px;padding:10px 12px}.spec-tile-label{font-size:.72rem;color:var(--muted);margin-bottom:4px}.spec-tile-val{font-size:.9rem;font-weight:600;color:var(--text)}
.kv-list{display:flex;flex-direction:column}.kv-row{display:flex;justify-content:space-between;align-items:flex-start;padding:9px 0;border-bottom:1px solid var(--rule);font-size:.84rem;gap:12px}.kv-row:last-child{border-bottom:0}.kv-key{color:var(--muted)}.kv-val{color:var(--text);text-align:right;font-weight:500}
.status-pill{display:inline-flex;align-items:center;gap:5px;min-height:22px;padding:2px 8px;border-radius:4px;font-size:.72rem;font-weight:600;white-space:nowrap}.status-pill.positive{background:#e7f2e9;color:#265b3d;border:1px solid #d1e5d5}.status-pill.warning{background:#f7f0df;color:#79551d;border:1px solid #eadbb7}.status-pill.negative{background:#f8e9e6;color:#913d35;border:1px solid #ebd1cc}.status-pill.neutral{background:#edf0ed;color:#59635b;border:1px solid #dfe4df}
.chip-group{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.mat-chip{background:#edf2ee;border:1px solid #d9e3da;color:#375d42;font-size:.74rem;font-weight:500;padding:3px 8px;border-radius:4px}
.clean-table{width:100%;border-collapse:collapse;font-size:.84rem}.clean-table th{text-align:left;font-size:.75rem;font-weight:500;color:var(--muted);padding:9px 10px;border-bottom:1px solid var(--border)}.clean-table th.num,.clean-table td.num{text-align:right;font-family:'IBM Plex Mono',monospace;font-variant-numeric:tabular-nums}.clean-table td{padding:10px;border-bottom:1px solid var(--rule);color:var(--text);vertical-align:middle}.clean-table tr:last-child td{border-bottom:0}
.bar-list-row{margin-bottom:11px}.bar-list-top{display:flex;justify-content:space-between;font-size:.82rem;font-weight:500;margin-bottom:5px}.bar-list-track{width:100%;height:5px;background:#edf0ed;border-radius:2px;overflow:hidden}.bar-list-fill{height:100%;background:var(--accent);border-radius:2px}
div[data-baseweb="input"],div[data-baseweb="select"]>div,div[data-baseweb="textarea"]{border-radius:var(--radius-control)!important;background:#fff!important;border:1px solid var(--control)!important;box-shadow:none!important;transition:border-color .15s ease,box-shadow .15s ease!important}div[data-baseweb="input"]:focus-within,div[data-baseweb="select"]>div:focus-within,div[data-baseweb="textarea"]:focus-within{border-color:var(--accent)!important;box-shadow:0 0 0 2px rgba(46,100,74,.14)!important}
.stTextInput label,.stSelectbox label,.stNumberInput label,.stTextArea label,.stFileUploader label,.stDateInput label,.stTimeInput label{font-size:.82rem!important;font-weight:500!important;color:var(--muted)!important}
button[kind="primary"],[data-testid="stFormSubmitButton"] button{background:var(--accent)!important;color:#fff!important;border:1px solid var(--accent)!important;border-radius:5px!important;font-weight:600!important;font-size:.85rem!important;min-height:40px!important;padding:0 16px!important;box-shadow:none!important;transition:background .15s ease,border-color .15s ease!important}button[kind="primary"] *{color:#fff!important}button[kind="primary"]:hover,[data-testid="stFormSubmitButton"] button:hover{background:#254f3a!important;border-color:#254f3a!important;transform:none!important}
button[kind="secondary"],.stDownloadButton button,.stLinkButton a{background:#fff!important;color:var(--text)!important;border:1px solid var(--control)!important;border-radius:5px!important;font-weight:500!important;font-size:.84rem!important;min-height:38px!important;box-shadow:none!important;text-decoration:none!important}button[kind="secondary"]:hover,.stDownloadButton button:hover,.stLinkButton a:hover{border-color:var(--accent)!important;background:var(--raised)!important}
div[data-testid="stForm"]{background:var(--raised)!important;border:1px solid var(--border)!important;border-radius:7px!important;padding:20px!important;box-shadow:none!important}iframe{border:1px solid var(--border)!important;border-radius:7px!important;display:block!important;width:100%!important;box-shadow:none!important}
[data-testid="stDataFrame"],[data-testid="stTable"]{border:1px solid var(--border);border-radius:6px;overflow:hidden}
[data-testid="stAlert"]{border-radius:5px!important}
a{color:var(--accent)}:focus-visible{outline:2px solid var(--accent)!important;outline-offset:2px!important}
@media(max-width:768px){.spec-grid{grid-template-columns:1fr 1fr}div[data-testid="stForm"]{padding:15px!important}.clean-table{display:block;overflow-x:auto;white-space:nowrap}}
"""
